/// `MCP_RESOURCE_URL=https://mcp.example.test/mcp`, with `BASE_URL` the
/// issuer's host, resolved as startup resolves it.
fn published() -> OAuth2ServerConfig {
    OAuth2ServerConfig {
        issuer_url: ISSUER.to_owned(),
        mcp_resource_url: MCP_RESOURCE.to_owned(),
        mcp_resource_aliases: resolve_mcp_resource_aliases(MCP_RESOURCE, Some(ISSUER)),
        ..OAuth2ServerConfig::default()
    }
}

async fn resources() -> Arc<ServerContext> {
    Box::pin(create_test_server_resources_with_config(ServerConfig {
        oauth2_server: published(),
        activity_fetch_limit: 100,
        ..ServerConfig::default()
    }))
    .await
    .unwrap()
}

fn a2a_routes(resources: &Arc<ServerContext>) -> Router {
    let tool_runtime: Arc<dyn ToolRuntime> = resources.clone();
    A2ARoutes::routes(A2ARoutesState {
        ctx: resources.clone(),
        client_manager: resources.a2a.a2a_client_manager.clone(),
        auth_middleware: resources.auth.auth_middleware.clone(),
        tool_runtime,
        coaching: None,
    })
}

fn oauth2_routes(resources: &Arc<ServerContext>) -> Router {
    let context = OAuth2Context {
        database: resources.agent.database.clone(),
        oauth2_server: resources.common.repos.oauth2_server.clone(),
        tenants: resources.common.repos.tenants.clone(),
        users: resources.common.repos.users.clone(),
        auth_manager: resources.auth.auth_manager.clone(),
        jwks_manager: resources.auth.jwks_manager.clone(),
        config: Arc::new(resources.common.config.oauth2_server.clone()),
        rate_limiter: Arc::new(OAuth2RateLimiter::new(
            None,
            OAuth2RateLimiter::local_window_store(),
            &resources.common.config.rate_limiting,
        )),
        refresh_token_expiry_days: 30,
        csrf_manager: resources.auth.csrf_manager.clone(),
        accounts: resources.account_service(),
        google_sign_in: None,
        strings: Arc::new(MessagingStringsRegistry::new()),
        first_party_only_sources: Arc::default(),
    };
    OAuth2Routes::routes(context).layer(MockConnectInfo(SocketAddr::from(([127, 0, 0, 1], 40_902))))
}

// ============================== the card ==============================

/// A validator for the 1.0.1 `AgentCard`, over the schema fixture.
fn card_validator() -> Validator {
    let bundle: Value =
        serde_json::from_str(include_str!("../fixtures/a2a/a2a-1.0.1.schema.json")).unwrap();
    let mut definitions = bundle["definitions"].as_object().unwrap().clone();
    let names: Vec<String> = definitions.keys().cloned().collect();
    for definition in definitions.values_mut() {
        if let Some(fields) = definition.as_object_mut() {
            fields.remove("$schema");
        }
        point_refs_at_definitions(definition, &names);
    }
    jsonschema::validator_for(&json!({
        "$ref": "#/definitions/Agent%20Card",
        "definitions": definitions,
    }))
    .expect("the 1.0.1 AgentCard schema compiles")
}

/// Rewrite `{"$ref": "lf.a2a.v1.AgentInterface.jsonschema.json"}` to the
/// bundle's own `#/definitions/Agent%20Interface`.
///
/// A definition's name is its message name with spaces added; the reference
/// names the message itself, so the two match once the spaces are gone.
fn point_refs_at_definitions(schema: &mut Value, names: &[String]) {
    match schema {
        Value::Object(fields) => {
            for (key, value) in &mut *fields {
                if key == "$ref" {
                    let target = definition_ref(value.as_str().unwrap(), names);
                    *value = Value::String(target);
                } else {
                    point_refs_at_definitions(value, names);
                }
            }
        }
        Value::Array(items) => {
            for item in items {
                point_refs_at_definitions(item, names);
            }
        }
        _ => {}
    }
}

/// The local reference for a file reference of the bundle.
fn definition_ref(file_ref: &str, names: &[String]) -> String {
    let message = file_ref
        .strip_suffix(".jsonschema.json")
        .and_then(|name| name.rsplit('.').next())
        .unwrap_or_else(|| panic!("unexpected $ref {file_ref}"));
    let name = names
        .iter()
        .find(|name| name.replace(' ', "") == message)
        .unwrap_or_else(|| panic!("no definition for {message}"));
    format!("#/definitions/{}", name.replace(' ', "%20"))
}

fn violations(validator: &Validator, card: &Value) -> Vec<String> {
    validator
        .iter_errors(card)
        .map(|error| format!("{}: {error}", error.instance_path()))
        .collect()
}

async fn served_card(resources: &Arc<ServerContext>, host: &str) -> Value {
    let response = AxumTestRequest::get("/.well-known/agent-card.json")
        .header("x-forwarded-host", host)
        .send(a2a_routes(resources))
        .await;
    assert_eq!(response.status(), 200);
    response.json()
}

#[tokio::test]
async fn the_served_card_validates_against_the_1_0_1_schema() {
    let resources = resources().await;
    let card = served_card(&resources, DOOR_HOST).await;

    let problems = violations(&card_validator(), &card);
    assert!(problems.is_empty(), "{problems:#?}\n{card:#}");
}

/// A validator that accepts anything proves nothing, so each shape the card
/// must not take must fail it.
#[tokio::test]
async fn the_schema_check_refuses_what_the_card_must_not_be() {
    let resources = resources().await;
    let good = served_card(&resources, DOOR_HOST).await;
    let validator = card_validator();
    assert_eq!(violations(&validator, &good), Vec::<String>::new());

    let mut values_not_list = good.clone();
    values_not_list["securityRequirements"][0]["schemes"]["oauth2AuthorizationCode"] =
        json!({ "values": ["fitness:read", "profile:read"] });
    assert!(
        !violations(&validator, &values_not_list).is_empty(),
        "StringList's member is `list`"
    );

    let mut unknown_member = good.clone();
    unknown_member["iconURL"] = json!("https://example.test/icon.png");
    assert!(
        !violations(&validator, &unknown_member).is_empty(),
        "the card takes no member the schema does not name"
    );

    let mut wrong_type = good;
    wrong_type["securitySchemes"]["oauth2AuthorizationCode"]["oauth2SecurityScheme"]["flows"]
        ["authorizationCode"]["pkceRequired"] = json!("true");
    assert!(
        !violations(&validator, &wrong_type).is_empty(),
        "pkceRequired is a boolean"
    );
}

/// The card must not read differently by host: a registry and an agent
/// reaching it through either get the published door.
#[tokio::test]
async fn the_card_names_the_published_door_whichever_host_serves_it() {
    let resources = resources().await;

    for host in [DOOR_HOST, APP_HOST] {
        let card = served_card(&resources, host).await;
        let interfaces: Vec<(&str, &str)> = card["supportedInterfaces"]
            .as_array()
            .unwrap()
            .iter()
            .map(|i| {
                (
                    i["protocolBinding"].as_str().unwrap(),
                    i["url"].as_str().unwrap(),
                )
            })
            .collect();
        assert_eq!(
            interfaces,
            [
                ("JSONRPC", "https://mcp.example.test/a2a/jsonrpc"),
                ("HTTP+JSON", "https://mcp.example.test/a2a"),
            ],
            "via {host}"
        );
        assert_eq!(card["iconUrl"], format!("{DOOR}{ICON_PATH}"));
        assert_eq!(card["documentationUrl"], "https://dravr.ai/docs");
    }
}

#[tokio::test]
async fn the_card_offers_the_authorization_code_flow_on_the_issuer_and_keeps_client_credentials() {
    let resources = resources().await;
    let card = served_card(&resources, DOOR_HOST).await;

    let scheme = &card["securitySchemes"]["oauth2AuthorizationCode"]["oauth2SecurityScheme"];
    assert_eq!(
        scheme["oauth2MetadataUrl"],
        "https://app.example.test/.well-known/oauth-authorization-server"
    );
    let flow = &scheme["flows"]["authorizationCode"];
    assert_eq!(
        flow["authorizationUrl"],
        "https://app.example.test/oauth2/authorize"
    );
    assert_eq!(flow["tokenUrl"], "https://app.example.test/oauth2/token");
    assert_eq!(flow["pkceRequired"], true);
    assert_eq!(
        flow["scopes"].as_object().unwrap().len(),
        OAuthScope::delegable_as_str().len()
    );

    let b2b = &card["securitySchemes"]["oauth2ClientCredentials"]["oauth2SecurityScheme"];
    assert_eq!(
        b2b["flows"]["clientCredentials"]["tokenUrl"],
        "https://app.example.test/oauth2/token"
    );
    assert!(
        b2b["flows"].get("authorizationCode").is_none(),
        "a oneof: a scheme offers one flow"
    );

    assert_eq!(
        card["securityRequirements"][0]["schemes"]["oauth2AuthorizationCode"]["list"],
        json!(["fitness:read", "profile:read"]),
        "the marketplace path comes first, asking for the grant the coaching skill needs too"
    );
}

/// What the card's OAuth URLs promise is what the issuer's own document says.
#[tokio::test]
async fn the_card_agrees_with_the_issuer_metadata_document() {
    let resources = resources().await;
    let card = served_card(&resources, DOOR_HOST).await;
    let metadata: Value = AxumTestRequest::get("/.well-known/oauth-authorization-server")
        .send(oauth2_routes(&resources))
        .await
        .json();

    let flow = &card["securitySchemes"]["oauth2AuthorizationCode"]["oauth2SecurityScheme"]["flows"]
        ["authorizationCode"];
    assert_eq!(flow["authorizationUrl"], metadata["authorization_endpoint"]);
    assert_eq!(flow["tokenUrl"], metadata["token_endpoint"]);
    assert_eq!(
        metadata["code_challenge_methods_supported"],
        json!(["S256"])
    );
}

/// The extended card is a second builder call: it must not fall back to
/// another host.
#[tokio::test]
async fn the_extended_card_names_the_same_door() {
    let resources = resources().await;
    let (user, _) = common::create_test_tenant(&resources, "door-extended@example.com")
        .await
        .unwrap();
    let token = delegated_token(&resources, &user, None, &grant()).await;

    let card: Value = AxumTestRequest::get("/a2a/extendedAgentCard")
        .header("A2A-Version", "1.0")
        .header("Authorization", &format!("Bearer {token}"))
        .send(a2a_routes(&resources))
        .await
        .json();
    assert_eq!(
        card["supportedInterfaces"][0]["url"],
        "https://mcp.example.test/a2a/jsonrpc"
    );
    let problems = violations(&card_validator(), &card);
    assert!(problems.is_empty(), "{problems:#?}");
}

