// ============================ the challenge ============================

/// One refused call per binding and per shape of route.
fn refused_calls() -> Vec<(&'static str, AxumTestRequest)> {
    let send_message = json!({
        "message": {
            "messageId": "m-door",
            "role": "ROLE_USER",
            "parts": [{ "data": { "tool_name": "get_athlete", "parameters": {} } }]
        }
    });
    vec![
        (
            "JSON-RPC",
            AxumTestRequest::post("/a2a/jsonrpc")
                .header("A2A-Version", "1.0")
                .json(&json!({"jsonrpc": "2.0", "method": "GetExtendedAgentCard", "id": 1})),
        ),
        (
            "JSON-RPC streaming",
            AxumTestRequest::post("/a2a/jsonrpc")
                .header("A2A-Version", "1.0")
                .json(&json!({
                    "jsonrpc": "2.0",
                    "method": "SendStreamingMessage",
                    "params": send_message,
                    "id": 2
                })),
        ),
        (
            "REST send",
            AxumTestRequest::post("/a2a/message:send")
                .header("A2A-Version", "1.0")
                .json(&send_message),
        ),
        (
            "REST stream",
            AxumTestRequest::post("/a2a/message:stream")
                .header("A2A-Version", "1.0")
                .json(&send_message),
        ),
        (
            "REST get",
            AxumTestRequest::get("/a2a/tasks/some-task").header("A2A-Version", "1.0"),
        ),
        (
            "REST list",
            AxumTestRequest::get("/a2a/tasks").header("A2A-Version", "1.0"),
        ),
        (
            "REST subscribe (GET)",
            AxumTestRequest::get("/a2a/tasks/some-task:subscribe").header("A2A-Version", "1.0"),
        ),
        (
            "REST subscribe (POST)",
            AxumTestRequest::post("/a2a/tasks/some-task:subscribe").header("A2A-Version", "1.0"),
        ),
        (
            "REST cancel",
            AxumTestRequest::post("/a2a/tasks/some-task:cancel").header("A2A-Version", "1.0"),
        ),
        (
            "REST extended card",
            AxumTestRequest::get("/a2a/extendedAgentCard").header("A2A-Version", "1.0"),
        ),
    ]
}

#[tokio::test]
async fn every_refusal_on_either_binding_carries_the_challenge() {
    let resources = resources().await;
    let expected = "Bearer resource_metadata=\"https://mcp.example.test/.well-known/oauth-protected-resource/a2a\", \
                    scope=\"fitness:read profile:read\"";

    for (name, request) in refused_calls() {
        let response = request
            .header("x-forwarded-host", DOOR_HOST)
            .send(a2a_routes(&resources))
            .await;
        assert_eq!(response.status(), 401, "{name}");
        assert_eq!(
            response.header("www-authenticate"),
            Some(expected),
            "{name}"
        );
    }
}

#[tokio::test]
async fn a_credential_that_was_sent_and_refused_is_named_invalid() {
    let resources = resources().await;

    for (name, request) in refused_calls() {
        let response = request
            .header("x-forwarded-host", DOOR_HOST)
            .header("Authorization", "Bearer not-a-token")
            .send(a2a_routes(&resources))
            .await;
        assert_eq!(response.status(), 401, "{name}");
        assert_eq!(
            response.header("www-authenticate"),
            Some(
                "Bearer resource_metadata=\"https://mcp.example.test/.well-known/oauth-protected-resource/a2a\", \
                 error=\"invalid_token\", scope=\"fitness:read profile:read\""
            ),
            "{name}"
        );
    }
}

/// The URL a challenge names, read out of the header.
fn named_metadata_path(response: &AxumTestResponse, origin: &str) -> String {
    let challenge = response.header("www-authenticate").unwrap();
    let start = challenge.find("resource_metadata=\"").unwrap() + "resource_metadata=\"".len();
    let url = &challenge[start..];
    let url = &url[..url.find('"').unwrap()];
    url.strip_prefix(origin)
        .unwrap_or_else(|| panic!("{url} is not on {origin}"))
        .to_owned()
}

/// A challenge is only as good as the document it names: fetched as a client
/// would, the document exists and describes the resource the client called.
#[tokio::test]
async fn the_document_the_challenge_names_answers_and_describes_the_dialed_resource() {
    let resources = resources().await;

    for (host, origin, resource) in [
        (DOOR_HOST, DOOR, A2A_RESOURCE),
        (APP_HOST, ISSUER, A2A_RESOURCE_ON_APP),
    ] {
        let refused = AxumTestRequest::post("/a2a/jsonrpc")
            .header("A2A-Version", "1.0")
            .header("x-forwarded-host", host)
            .json(&json!({"jsonrpc": "2.0", "method": "ListTasks", "id": 1}))
            .send(a2a_routes(&resources))
            .await;
        assert_eq!(refused.status(), 401);

        let path = named_metadata_path(&refused, origin);
        let document = AxumTestRequest::get(&path)
            .header("x-forwarded-host", host)
            .send(oauth2_routes(&resources))
            .await;
        assert_eq!(document.status(), 200, "{path} via {host}");
        let metadata: Value = document.json();
        assert_eq!(metadata["resource"], resource, "via {host}");
        assert_eq!(metadata["authorization_servers"], json!([ISSUER]));
    }
}

/// Only a refusal is challenged, and only on the protocol surface: the
/// management routes refuse a delegated token, so naming a resource there
/// would send a client to authorize for a token they do not take.
#[tokio::test]
async fn nothing_but_a_protocol_refusal_is_challenged() {
    let resources = resources().await;

    let version_refused = AxumTestRequest::post("/a2a/jsonrpc")
        .json(&json!({"jsonrpc": "2.0", "method": "ListTasks", "id": 1}))
        .send(a2a_routes(&resources))
        .await;
    assert_eq!(version_refused.status(), 200);
    assert_eq!(version_refused.header("www-authenticate"), None);

    let card = AxumTestRequest::get("/.well-known/agent-card.json")
        .send(a2a_routes(&resources))
        .await;
    assert_eq!(card.header("www-authenticate"), None);

    let management = AxumTestRequest::get("/a2a/clients")
        .send(a2a_routes(&resources))
        .await;
    assert_eq!(management.status(), 401);
    assert_eq!(management.header("www-authenticate"), None);
}

// ============================= the audience =============================

/// The default grant, as a marketplace client's first connection holds it.
fn grant() -> Vec<String> {
    OAuthScope::default_grant()
        .iter()
        .map(ToString::to_string)
        .collect()
}

/// A delegated token for `user`, bound to `audience`.
async fn delegated_token(
    resources: &Arc<ServerContext>,
    user: &User,
    audience: Option<&str>,
    scopes: &[String],
) -> String {
    let tenants = resources
        .agent
        .database
        .repositories()
        .tenants
        .list_for_user(user.id)
        .await
        .unwrap();
    resources
        .auth
        .auth_manager
        .generate_oauth_access_token(
            &resources.auth.jwks_manager,
            &DelegatedGrant {
                client_id: "marketplace-client",
                scopes,
                audience,
            },
            &user.id,
            &[],
            tenants.first().map(|tenant| tenant.id.to_string()),
        )
        .unwrap()
}

/// `ListTasks` over both bindings with `token`; both must agree.
async fn list_tasks_status(resources: &Arc<ServerContext>, token: &str) -> u16 {
    let jsonrpc = AxumTestRequest::post("/a2a/jsonrpc")
        .header("A2A-Version", "1.0")
        .header("Authorization", &format!("Bearer {token}"))
        .json(&json!({"jsonrpc": "2.0", "method": "ListTasks", "params": {}, "id": 1}))
        .send(a2a_routes(resources))
        .await
        .status();
    let rest = AxumTestRequest::get("/a2a/tasks")
        .header("A2A-Version", "1.0")
        .header("Authorization", &format!("Bearer {token}"))
        .send(a2a_routes(resources))
        .await
        .status();
    assert_eq!(jsonrpc, rest, "the bindings disagree");
    rest
}

