/// carnet#768 is decided by the grant, not the audience: Dravr's own session
/// carries the full self grant, and naming the A2A resource does not turn it
/// into an agent's credential.
#[tokio::test]
async fn a_first_party_session_grant_stays_refused_with_the_a2a_audience() {
    let resources = resources().await;
    let (user, session) = common::create_test_tenant(&resources, "door-session@example.com")
        .await
        .unwrap();

    assert_eq!(list_tasks_status(&resources, &session).await, 401);

    let self_grant: Vec<String> = OAuthScope::self_grant()
        .iter()
        .map(ToString::to_string)
        .collect();
    let bound_session = delegated_token(&resources, &user, Some(A2A_RESOURCE), &self_grant).await;
    assert_eq!(list_tasks_status(&resources, &bound_session).await, 401);
}

#[tokio::test]
async fn a_client_credentials_token_keeps_authenticating_and_may_be_bound_to_a2a() {
    let resources = resources().await;
    let (user, _) = common::create_test_tenant(&resources, "door-b2b@example.com")
        .await
        .unwrap();
    let client = register_client(&resources, &user).await;

    for audience in [None, Some(A2A_RESOURCE)] {
        let token = resources
            .auth
            .auth_manager
            .generate_client_credentials_token(
                &resources.auth.jwks_manager,
                &client,
                &grant(),
                None,
                audience,
            )
            .unwrap();
        assert_eq!(
            list_tasks_status(&resources, &token).await,
            200,
            "{audience:?}"
        );
    }
    let foreign = resources
        .auth
        .auth_manager
        .generate_client_credentials_token(
            &resources.auth.jwks_manager,
            &client,
            &grant(),
            None,
            Some(MCP_RESOURCE),
        )
        .unwrap();
    assert_eq!(list_tasks_status(&resources, &foreign).await, 401);
}

async fn register_client(resources: &Arc<ServerContext>, user: &User) -> String {
    resources
        .a2a
        .a2a_client_manager
        .register_client(
            pierre_a2a::ClientRegistrationRequest {
                name: format!("door-client-{}", user.id),
                description: "public door test client".to_owned(),
                capabilities: Vec::new(),
                redirect_uris: Vec::new(),
                contact_email: "door@example.com".to_owned(),
            },
            user.id,
        )
        .await
        .unwrap()
        .client_id
}

// ========================= the subscribe verb =========================

/// Answer `method` on `uri` without reading the body: a live stream never ends.
async fn call(routes: Router, method: &str, uri: &str, token: &str) -> Response {
    routes
        .oneshot(
            Request::builder()
                .method(method)
                .uri(uri)
                .header("A2A-Version", "1.0")
                .header(header::AUTHORIZATION, format!("Bearer {token}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap()
}

fn content_type(response: &Response) -> &str {
    response
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default()
}

/// A working task of a client `user` registered, and that client's token.
async fn working_task(resources: &Arc<ServerContext>, user: &User) -> (String, String) {
    let client = register_client(resources, user).await;
    let repos = A2ACtx::repos(resources.as_ref());
    let task = repos
        .a2a
        .create_task(&client, None, "message", &json!({}), Some("ctx-door"))
        .await
        .unwrap();
    repos
        .a2a
        .update_task_status(&task, &TaskStatus::Working, None, None)
        .await
        .unwrap();
    let token = resources
        .auth
        .auth_manager
        .generate_client_credentials_token(
            &resources.auth.jwks_manager,
            &client,
            &grant(),
            None,
            None,
        )
        .unwrap();
    (task, token)
}

/// `GET /a2a/tasks/{id}:subscribe` is the subscribe verb, never `GetTask` on
/// the id `"<id>:subscribe"`, which does not exist.
#[tokio::test]
async fn a_get_on_the_subscribe_verb_opens_the_stream() {
    let resources = resources().await;
    let (user, _) = common::create_test_tenant(&resources, "door-subscribe@example.com")
        .await
        .unwrap();
    let (task, token) = working_task(&resources, &user).await;

    for method in ["GET", "POST"] {
        let response = call(
            a2a_routes(&resources),
            method,
            &format!("/a2a/tasks/{task}:subscribe"),
            &token,
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK, "{method}");
        assert!(
            content_type(&response).starts_with("text/event-stream"),
            "{method} answered {}",
            content_type(&response)
        );
    }
}

#[tokio::test]
async fn a_get_on_a_plain_id_stays_get_task() {
    let resources = resources().await;
    let (user, _) = common::create_test_tenant(&resources, "door-get@example.com")
        .await
        .unwrap();
    let (task, token) = working_task(&resources, &user).await;

    let response = AxumTestRequest::get(&format!("/a2a/tasks/{task}"))
        .header("A2A-Version", "1.0")
        .header("Authorization", &format!("Bearer {token}"))
        .send(a2a_routes(&resources))
        .await;
    assert_eq!(response.status(), 200);
    let body: Value = response.json();
    assert_eq!(body["id"], task.as_str());
}

/// `:subscribe` on a task the caller cannot see is that task's refusal, not an
/// id with a suffix, and a verb `GET` does not serve is not a task lookup.
#[tokio::test]
async fn a_get_on_any_other_verb_is_an_unknown_action() {
    let resources = resources().await;
    let (user, _) = common::create_test_tenant(&resources, "door-verb@example.com")
        .await
        .unwrap();
    let (task, token) = working_task(&resources, &user).await;

    for verb in ["cancel", "nonsense"] {
        let response = AxumTestRequest::get(&format!("/a2a/tasks/{task}:{verb}"))
            .header("A2A-Version", "1.0")
            .header("Authorization", &format!("Bearer {token}"))
            .send(a2a_routes(&resources))
            .await;
        assert_eq!(response.status(), 404, "{verb}");
        let body: Value = response.json();
        assert_eq!(body["error"]["message"], "Unknown task action", "{verb}");
    }

    let unknown_task = AxumTestRequest::get("/a2a/tasks/no-such-task:subscribe")
        .header("A2A-Version", "1.0")
        .header("Authorization", &format!("Bearer {token}"))
        .send(a2a_routes(&resources))
        .await;
    assert_eq!(unknown_task.status(), 404);
    let body: Value = unknown_task.json();
    assert_ne!(body["error"]["message"], "Unknown task action");
}

// ======================== what registration mints ========================

/// A client is handed the two things `/oauth2/token` verifies, and nothing
/// else: no Ed25519 private key nothing verifies, no API key authenticating as
/// a user of its own with nothing in it.
#[tokio::test]
async fn registration_hands_out_the_id_and_secret_and_mints_nothing_else() {
    let resources = resources().await;
    let (user, session) = common::create_test_tenant(&resources, "door-mint@example.com")
        .await
        .unwrap();
    let repos = A2ACtx::repos(resources.as_ref());

    let response = AxumTestRequest::post("/a2a/clients")
        .header("Authorization", &format!("Bearer {session}"))
        .json(&json!({
            "name": "door-mint-client",
            "description": "mints nothing else",
            "capabilities": ["fitness-data-analysis"],
            "contact_email": "door@example.com",
        }))
        .send(a2a_routes(&resources))
        .await;
    assert_eq!(response.status(), 201);
    let created: Value = response.json();
    let mut members: Vec<&str> = created
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .collect();
    members.sort_unstable();
    assert_eq!(members, ["client_id", "client_secret"], "{created}");
    let client_id = created["client_id"].as_str().unwrap();

    assert!(
        repos
            .users
            .get_by_email(&format!("a2a-system-{client_id}@pierre.ai"))
            .await
            .unwrap()
            .is_none(),
        "no system user: it existed only to hold the API key"
    );
    assert!(
        repos
            .api_keys
            .get_for_user(user.id)
            .await
            .unwrap()
            .is_empty(),
        "no API key"
    );

    let record: Value = AxumTestRequest::get(&format!("/a2a/clients/{client_id}"))
        .header("Authorization", &format!("Bearer {session}"))
        .send(a2a_routes(&resources))
        .await
        .json();
    for phantom in ["public_key", "permissions"] {
        assert!(record.get(phantom).is_none(), "{phantom}: {record}");
    }
    assert_eq!(record["capabilities"], json!(["fitness-data-analysis"]));
}

/// One user may register several clients, each with its own id and secret.
#[tokio::test]
async fn two_clients_register_side_by_side() {
    let resources = resources().await;
    let (user, _) = common::create_test_tenant(&resources, "door-two@example.com")
        .await
        .unwrap();

    let first = register_client(&resources, &user).await;
    let second = register_client(&resources, &user).await;
    assert_ne!(first, second);
}

/// An unknown label is not a refusal: it never decided anything.
#[tokio::test]
async fn a_client_may_declare_any_label_or_none() {
    let resources = resources().await;
    let (_, session) = common::create_test_tenant(&resources, "door-label@example.com")
        .await
        .unwrap();

    for body in [
        json!({"name": "n", "description": "d", "contact_email": "d@example.com"}),
        json!({"name": "n", "description": "d", "contact_email": "d@example.com",
               "capabilities": ["whatever-it-does"]}),
    ] {
        let response = AxumTestRequest::post("/a2a/clients")
            .header("Authorization", &format!("Bearer {session}"))
            .json(&body)
            .send(a2a_routes(&resources))
            .await;
        assert_eq!(response.status(), 201, "{body}");
    }
}
